-- Insert only problems with id > 31 (she already has 1..31)
-- Safe to re-run: skips existing ids
BEGIN;

CREATE TEMP TABLE tmp_problems (LIKE problems INCLUDING DEFAULTS);

SELECT id, title, description, difficulty, examples, constraints_data, test_cases, created_at, topics
FROM tmp_problems t
WHERE NOT EXISTS (SELECT 1 FROM problems p WHERE p.id = t.id);

SELECT setval(
  pg_get_serial_sequence('problems', 'id'),
  GREATEST((SELECT COALESCE(MAX(id), 1) FROM problems), 1)
);

COMMIT;

